// src/utils/claudeApi.js
// Single place to call Claude — all pages import this.
// Proxy at localhost:5001 handles the real Anthropic API key.

const PROXY = "http://localhost:5001/api/claude";

/**
 * callClaude({ system, userMessage, tools? })
 * Returns the parsed response data from Anthropic.
 */
export async function callClaude({ system, userMessage, tools = [], maxTokens = 4000 }) {
  const body = {
    model:      "claude-sonnet-4-20250514",
    max_tokens: maxTokens,
    system,
    messages: [{ role: "user", content: userMessage }],
  };

  // Only include tools field when tools are requested
  if (tools.length > 0) {
    body.tools = tools;
  }

  const res = await fetch(PROXY, {
    method:  "POST",
    headers: { "Content-Type": "application/json" },
    body:    JSON.stringify(body),
  });

  if (!res.ok) {
    const err = await res.json().catch(() => ({}));
    throw new Error(err?.error?.message || `HTTP ${res.status}`);
  }

  return res.json(); // returns full Anthropic response {id, content, ...}
}

/**
 * extractText(data) — pull all text blocks from Anthropic response
 */
export function extractText(data) {
  return (data?.content || [])
    .filter(b => b.type === "text")
    .map(b => b.text)
    .join("");
}

/**
 * WEB_SEARCH_TOOL — pass in tools array to enable web search
 */
export const WEB_SEARCH_TOOL = [
  { type: "web_search_20250305", name: "web_search" },
];
